//! Architectural 2D views: `elevation`, `section` and `view.delete`, linked regeneration, and the `views` report of
//! `arch.inspect`.
//!
//! A view lives in the arch model (so it undoes, saves and audits with the drawing). Its geometry is generated by
//! `cadcraft_arch3d::views` and regenerated whenever `arch_revision` moves — by [`refresh_views`], which
//! `Session::after_command` and `open_drawing` call.

use serde_json::{Value, json};

use cadcraft_arch::interior::{face_of, wall_on_side};
use cadcraft_arch::plan::ring_label_point;
use cadcraft_doc::ArchId;
use cadcraft_doc::arch::Room;
use cadcraft_geom::Vec2;

use cadcraft_doc::arch::{
    ArchKind, ArchModel, ArchView, DimKind, NoteKind, ViewKind, handle_json, note_label, room_label, view_handle, view_label, wall_label,
};

use crate::cmd::{CommandSpec, bad};
use crate::{EngineError, Result, Session};

/// Smallest accepted look-vector length.
const MIN_LOOK: f64 = 1e-9;
/// Largest accepted look component magnitude (the same bound as view coordinates).
const MAX_COORD: f64 = 1e6;

/// Command specs for the view commands.
pub fn specs() -> Vec<CommandSpec> {
    vec![
        CommandSpec::new("elevation", "Elevation", run_elevation)
            .menu(&["Architecture", "Elevation"])
            .alias(&["elev"])
            .params("{side?: south|north|east|west, look?: [dx,dy], name?, insert?: [x,y], scale?, scope?: [[x0,y0],[x1,y1]], dimensions?: bool, room?: \"r0\"|name, level?: name|index, wall?: \"w5\"}"),
        CommandSpec::new("section", "Section", run_section)
            .menu(&["Architecture", "Section"])
            .alias(&["sect"])
            .params("{from: [x,y], to: [x,y], look?, depth?, name?, insert?, scale?, scope?, dimensions?}"),
        CommandSpec::new("view.delete", "Delete View", run_view_delete).menu(&["Architecture", "Delete View"]).params("{view: \"v0\"}"),
    ]
}

/// The value of `key` unless it is absent or null.
fn present<'a>(p: &'a Value, key: &str) -> Option<&'a Value> {
    match p.get(key) {
        None | Some(Value::Null) => None,
        Some(v) => Some(v),
    }
}

/// A `[x, y]` pair of finite numbers.
fn pair(cmd: &str, key: &str, v: &Value) -> Result<[f64; 2]> {
    let err = || bad(cmd, format!("`{key}` must be [x, y] with two finite numbers"));
    let a = v.as_array().filter(|a| a.len() == 2).ok_or_else(err)?;
    let x = a.first().and_then(Value::as_f64).filter(|n| n.is_finite()).ok_or_else(err)?;
    let y = a.get(1).and_then(Value::as_f64).filter(|n| n.is_finite()).ok_or_else(err)?;
    Ok([x, y])
}

fn pair_opt(cmd: &str, p: &Value, key: &str) -> Result<Option<[f64; 2]>> {
    present(p, key).map(|v| pair(cmd, key, v)).transpose()
}

fn num_opt(cmd: &str, p: &Value, key: &str) -> Result<Option<f64>> {
    match present(p, key) {
        None => Ok(None),
        Some(v) => v.as_f64().filter(|n| n.is_finite()).map(Some).ok_or_else(|| bad(cmd, format!("`{key}` must be a finite number"))),
    }
}

/// A look vector, normalised; refused when not finite or shorter than [`MIN_LOOK`].
fn unit_look(cmd: &str, v: [f64; 2]) -> Result<[f64; 2]> {
    let len = v[0].hypot(v[1]);
    if !len.is_finite() || len <= MIN_LOOK || v.iter().any(|c| c.abs() > MAX_COORD) {
        return Err(bad(cmd, "`look` must be a direction with components within 1e6 and a length above 1e-9"));
    }
    Ok([v[0] / len, v[1] / len])
}

/// The options both commands share, parsed into a view on `base` (kind, look, cut and depth are set by the caller).
fn common(cmd: &str, p: &Value, base: &mut ArchView) -> Result<()> {
    if let Some(v) = present(p, "name") {
        base.name = v.as_str().ok_or_else(|| bad(cmd, "`name` must be a string"))?.to_string();
    }
    if let Some(i) = pair_opt(cmd, p, "insert")? {
        base.insert = i;
    }
    if let Some(sc) = num_opt(cmd, p, "scale")? {
        base.scale = sc;
    }
    if let Some(v) = present(p, "scope") {
        let a = v.as_array().filter(|a| a.len() == 2).ok_or_else(|| bad(cmd, "`scope` must be [[x0,y0],[x1,y1]]"))?;
        let c0 = pair(cmd, "scope", a.first().unwrap_or(&Value::Null))?;
        let c1 = pair(cmd, "scope", a.get(1).unwrap_or(&Value::Null))?;
        base.scope = Some([[c0[0].min(c1[0]), c0[1].min(c1[1])], [c0[0].max(c1[0]), c0[1].max(c1[1])]]);
    }
    if let Some(v) = present(p, "dimensions") {
        base.dimensions = v.as_bool().ok_or_else(|| bad(cmd, "`dimensions` must be true or false"))?;
    }
    Ok(())
}

/// Validate `view`, store it, generate its geometry at once and describe it.
fn create(s: &mut Session, cmd: &str, view: ArchView, layers: &[&str]) -> Result<Value> {
    view.validate().map_err(|e| bad(cmd, format!("invalid view: {e}")))?;
    let doc = s.doc_mut()?;
    let id = doc.arch.push_view(view).map_err(|e| bad(cmd, format!("{e}")))?;
    for l in layers {
        doc.ensure_layer(l);
    }
    doc.touch_arch();
    let rev = doc.arch_revision;
    cadcraft_arch3d::views::refresh(&mut doc.arch, rev);
    let v = doc.arch.view(id).ok_or_else(|| EngineError::Other("the new view vanished".into()))?;
    let (lines, rings) = v.generated.as_ref().map_or((0, 0), |g| (g.lines.len(), g.rings.len()));
    Ok(json!({ "view": view_label(id), "handle": handle_json(view_handle(id)), "name": v.name, "lines": lines, "rings": rings }))
}

/// The id of a label such as `r3` (prefix `r`), case-insensitive.
fn label_id(raw: &str, prefix: char) -> Option<ArchId> {
    let t = raw.trim().to_ascii_lowercase();
    t.strip_prefix(prefix)?.parse::<u32>().ok().map(ArchId)
}

/// A level index from a name or an index.
fn level_of(cmd: &str, arch: &ArchModel, v: &Value) -> Result<u32> {
    let found = match v {
        Value::Number(n) => n.as_u64().and_then(|i| u32::try_from(i).ok()).filter(|i| arch.level(*i).is_some()),
        Value::String(n) => arch.levels.iter().find(|l| l.name.trim().eq_ignore_ascii_case(n.trim())).map(|l| l.index),
        _ => None,
    };
    found.ok_or_else(|| bad(cmd, "`level` must be the name or index of a level of the drawing"))
}

/// The room `raw` names (a label or a room name), among the rooms of `level` when given.
fn find_room<'a>(cmd: &str, arch: &'a ArchModel, raw: &str, level: Option<u32>) -> Result<&'a Room> {
    let on_level = |r: &&Room| level.is_none_or(|l| r.level == l);
    let mut found: Vec<&Room> = label_id(raw, 'r').and_then(|id| arch.room(id)).into_iter().filter(on_level).collect();
    if found.is_empty() {
        let name = raw.trim();
        found = arch.rooms.iter().filter(|r| !name.is_empty() && r.name.trim().eq_ignore_ascii_case(name)).filter(on_level).collect();
    }
    match found.as_slice() {
        [r] => Ok(r),
        [] => Err(bad(cmd, format!("`room`: no room `{}`", raw.trim()))),
        _ => Err(bad(cmd, format!("`room`: `{}` names several rooms; give a room label or a `level`", raw.trim()))),
    }
}

/// The compass word nearest to a look direction.
fn compass(look: [f64; 2]) -> &'static str {
    if look[0].abs() >= look[1].abs() {
        if look[0] >= 0.0 { "East" } else { "West" }
    } else if look[1] >= 0.0 {
        "North"
    } else {
        "South"
    }
}

/// `elevation` with a `room`: the interior elevation of one wall of a room.
fn run_interior_elevation(s: &mut Session, p: &Value, room_v: &Value) -> Result<Value> {
    const CMD: &str = "elevation";
    if present(p, "look").is_some() {
        return Err(bad(CMD, "`look` cannot be given with `room`; name the `wall` or the `side`"));
    }
    if present(p, "scope").is_some() {
        return Err(bad(CMD, "`scope` cannot be given with `room`"));
    }
    let raw = room_v.as_str().ok_or_else(|| bad(CMD, "`room` must be a room label or name"))?;
    let (wall_v, side_v) = (present(p, "wall"), present(p, "side"));
    let (face, level, room_id, room_name, point) = {
        let arch = &s.doc()?.arch;
        let level = present(p, "level").map(|v| level_of(CMD, arch, v)).transpose()?;
        let room = find_room(CMD, arch, raw, level)?;
        let face = match (wall_v, side_v) {
            (Some(_), Some(_)) => return Err(bad(CMD, "give `wall` or `side`, not both")),
            (None, None) => return Err(bad(CMD, "`wall` (such as \"w5\") or `side` (south|north|east|west) is required with `room`")),
            (Some(w), None) => {
                let label = w.as_str().ok_or_else(|| bad(CMD, "`wall` must be a wall label such as \"w5\""))?;
                let id = label_id(label, 'w').filter(|id| arch.wall(*id).is_some()).ok_or_else(|| bad(CMD, format!("`wall`: no wall `{label}`")))?;
                face_of(arch, room, id).ok_or_else(|| bad(CMD, format!("`wall`: {label} does not bound the room")))?
            }
            (None, Some(sd)) => {
                let side = sd
                    .as_str()
                    .filter(|t| matches!(*t, "south" | "north" | "east" | "west"))
                    .ok_or_else(|| bad(CMD, "`side` must be south, north, east or west"))?;
                wall_on_side(arch, room, side).ok_or_else(|| bad(CMD, format!("`side`: the room has no wall on its {side} side")))?
            }
        };
        let n = room.polygon.len();
        let point = ring_label_point(&room.polygon, &room.holes).or_else(|| {
            let (sx, sy) = room.polygon.iter().fold((0.0, 0.0), |a, v| (a.0 + v.x, a.1 + v.y));
            (n > 0).then(|| Vec2::new(sx / n as f64, sy / n as f64))
        });
        let point = point.filter(|q| q.is_finite()).ok_or_else(|| bad(CMD, "the room has no usable outline"))?;
        (face, room.level, room.id, room.name.trim().to_string(), point)
    };
    // Axis-aligned walls give exactly axis-aligned looks (no 1e-16 residue from the wall's rotation).
    let snap = |c: f64| if c.abs() < 1e-12 { 0.0 } else { c };
    let look = [snap(face.look.x), snap(face.look.y)];
    let n_views = s.doc()?.arch.views.len();
    let who = if room_name.is_empty() { room_label(room_id) } else { room_name };
    let mut v = ArchView {
        name: format!("{who} {} Interior", compass(look)),
        kind: ViewKind::Interior,
        look,
        insert: [0.0, -15.0 * (n_views as f64 + 1.0)],
        dimensions: true,
        layer: "A-ELEV".into(),
        room: Some(room_id),
        room_point: Some([point.x, point.y]),
        wall: Some(face.wall),
        level: Some(level),
        ..Default::default()
    };
    common(CMD, p, &mut v)?;
    create(s, CMD, v, &["A-ELEV"])
}

fn run_elevation(s: &mut Session, p: &Value) -> Result<Value> {
    const CMD: &str = "elevation";
    if let Some(room) = present(p, "room") {
        return run_interior_elevation(s, p, room);
    }
    let side = present(p, "side");
    let look = pair_opt(CMD, p, "look")?;
    let (look, default_name) = match (side, look) {
        (Some(_), Some(_)) => return Err(bad(CMD, "give `side` or `look`, not both")),
        (None, None) => return Err(bad(CMD, "`side` (south|north|east|west) or `look` ([dx,dy]) is required")),
        (Some(v), None) => match v.as_str() {
            Some("south") => ([0.0, 1.0], Some("South Elevation")),
            Some("north") => ([0.0, -1.0], Some("North Elevation")),
            Some("east") => ([-1.0, 0.0], Some("East Elevation")),
            Some("west") => ([1.0, 0.0], Some("West Elevation")),
            _ => return Err(bad(CMD, "`side` must be south, north, east or west")),
        },
        (None, Some(l)) => (unit_look(CMD, l)?, None),
    };
    let n_views = s.doc()?.arch.views.len();
    let mut v = ArchView {
        name: default_name.map_or_else(|| format!("Elevation {}", n_views + 1), str::to_string),
        kind: ViewKind::Elevation,
        look,
        insert: [0.0, -15.0 * (n_views as f64 + 1.0)],
        dimensions: true,
        layer: "A-ELEV".into(),
        ..Default::default()
    };
    common(CMD, p, &mut v)?;
    create(s, CMD, v, &["A-ELEV"])
}

fn run_section(s: &mut Session, p: &Value) -> Result<Value> {
    const CMD: &str = "section";
    let from = pair_opt(CMD, p, "from")?.ok_or_else(|| bad(CMD, "`from` ([x, y]) is required"))?;
    let to = pair_opt(CMD, p, "to")?.ok_or_else(|| bad(CMD, "`to` ([x, y]) is required"))?;
    let look = match pair_opt(CMD, p, "look")? {
        Some(l) => unit_look(CMD, l)?,
        None => unit_look(CMD, [-(to[1] - from[1]), to[0] - from[0]])?,
    };
    let depth = num_opt(CMD, p, "depth")?;
    let (n_views, n_sections) = {
        let views = &s.doc()?.arch.views;
        (views.len(), views.iter().filter(|v| v.kind == ViewKind::Section).count())
    };
    let mut v = ArchView {
        name: format!("Section {}", n_sections + 1),
        kind: ViewKind::Section,
        look,
        cut: Some([from, to]),
        depth,
        insert: [0.0, -15.0 * (n_views as f64 + 1.0)],
        dimensions: true,
        layer: "A-SECT".into(),
        ..Default::default()
    };
    common(CMD, p, &mut v)?;
    create(s, CMD, v, &["A-SECT", "A-SECT-MCUT"])
}

fn run_view_delete(s: &mut Session, p: &Value) -> Result<Value> {
    const CMD: &str = "view.delete";
    let label = present(p, "view").and_then(Value::as_str).ok_or_else(|| bad(CMD, "`view` (such as \"v0\") is required"))?;
    let id = s.doc()?.arch.view_by_label(label).map(|v| v.id).ok_or_else(|| bad(CMD, format!("no view `{label}`")))?;
    s.doc_mut()?.arch.remove_view(id);
    Ok(json!({ "deleted": label }))
}

/// Regenerate every view whose geometry is missing or for another `arch_revision`. The revision is not touched, and
/// the document is only copied when something is stale.
pub(crate) fn refresh_views(s: &mut Session) {
    let stale = s.doc().is_ok_and(|d| d.arch.views.iter().any(|v| v.is_stale(d.arch_revision)));
    if !stale {
        return;
    }
    if let Ok(d) = s.doc_mut() {
        let rev = d.arch_revision;
        cadcraft_arch3d::views::refresh(&mut d.arch, rev);
    }
}

fn pt(p: [f64; 2]) -> Value {
    json!([p[0], p[1]])
}

fn rect(r: Option<[[f64; 2]; 2]>) -> Value {
    r.map_or(Value::Null, |r| json!([pt(r[0]), pt(r[1])]))
}

/// The `views` array of `arch.inspect`, in id order.
pub(crate) fn views_json(arch: &ArchModel) -> Value {
    let mut views: Vec<&ArchView> = arch.views.iter().collect();
    views.sort_by_key(|v| v.id);
    Value::Array(
        views
            .into_iter()
            .map(|v| {
                let g = v.generated.as_ref();
                let lines: Vec<Value> = g
                    .map(|g| {
                        g.lines.iter().map(|l| json!({ "a": pt(l.a), "b": pt(l.b), "kind": l.kind.key(), "id": l.kind.label(l.object) })).collect()
                    })
                    .unwrap_or_default();
                let rings: Vec<Value> = g
                    .map(|g| {
                        g.rings
                            .iter()
                            .map(|r| {
                                json!({
                                    "kind": r.kind.key(), "id": r.kind.label(r.object), "material": r.material,
                                    "points": r.points.iter().map(|p| pt(*p)).collect::<Vec<_>>(), "area": r.area(),
                                })
                            })
                            .collect()
                    })
                    .unwrap_or_default();
                let dims: Vec<Value> = g
                    .map(|g| {
                        g.dims
                            .iter()
                            .map(|d| {
                                let kind = match d.kind {
                                    DimKind::Width => "width",
                                    DimKind::Height => "height",
                                };
                                json!({ "kind": kind, "a": pt(d.a), "b": pt(d.b), "at": pt(d.at), "value": d.value, "text": d.text })
                            })
                            .collect()
                    })
                    .unwrap_or_default();
                let patterns: Vec<Value> = g
                    .map(|g| {
                        g.patterns
                            .iter()
                            .map(|p| json!({ "a": pt(p.a), "b": pt(p.b), "id": p.kind.label(p.object), "material": p.material }))
                            .collect()
                    })
                    .unwrap_or_default();
                let indicators: Vec<Value> = g
                    .map(|g| g.indicators.iter().map(|l| json!({ "a": pt(l.a), "b": pt(l.b), "id": l.kind.label(l.object) })).collect())
                    .unwrap_or_default();
                let labels: Vec<Value> = g
                    .map(|g| {
                        g.labels
                            .iter()
                            .map(|l| json!({ "text": l.text, "at": pt(l.at), "height": l.height, "layer": l.layer, "id": l.kind.label(l.object) }))
                            .collect()
                    })
                    .unwrap_or_default();
                let notes: Vec<Value> = v
                    .notes
                    .iter()
                    .map(|n| {
                        let value = match (n.kind, n.b) {
                            (NoteKind::Dimension, Some(b)) => json!((b[0] - n.at[0]).hypot(b[1] - n.at[1])),
                            _ => Value::Null,
                        };
                        json!({
                            "id": note_label(n.id), "kind": n.kind.key(), "text": n.text, "at": pt(n.at), "b": n.b.map_or(Value::Null, pt),
                            "placed": pt(v.placed(n.at)), "height": n.height, "layer": n.layer,
                            "attach": n.attach.map_or(Value::Null, |a| json!({ "object": a.kind.label(a.object), "corner": a.corner.key() })),
                            "value": value, "detached": n.detached,
                        })
                    })
                    .collect();
                json!({
                    "id": view_label(v.id),
                    "handle": handle_json(ArchKind::View.handle(v.id)),
                    "name": v.name,
                    "kind": v.kind.key(),
                    "room": v.room.map(|r| room_label(r)),
                    "wall": v.wall.map(|w| wall_label(w)),
                    "look": pt(v.look),
                    "cut": rect(v.cut),
                    "depth": v.depth,
                    "scope": rect(v.scope),
                    "scale": v.scale,
                    "insert": pt(v.insert),
                    "dimensions": v.dimensions,
                    "layer": v.layer,
                    "revision": g.map(|g| g.revision),
                    "extent": g.map_or(json!([0.0, 0.0, 0.0, 0.0]), |g| json!(g.extent)),
                    "bounds": v.bounds().map_or(json!([0.0, 0.0, 0.0, 0.0]), |b| json!(b)),
                    "lines": lines,
                    "rings": rings,
                    "dims": dims,
                    "patterns": patterns,
                    "indicators": indicators,
                    "labels": labels,
                    "notes": notes,
                    "error": g.and_then(|g| g.error.clone()),
                })
            })
            .collect(),
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use cadcraft_doc::arch::{ArchId, Corner, NoteAttach, ViewGeometry, ViewLabel, ViewLine, ViewNote, ViewPatternLine};

    #[test]
    fn inspect_views_report_the_new_lists() {
        let mut m = ArchModel::default();
        let dim = ViewNote { id: 0, kind: NoteKind::Dimension, text: "d".into(), at: [0.0, 0.0], b: Some([3.0, 4.0]), ..ViewNote::default() };
        let attached = ViewNote {
            id: 1,
            text: "t".into(),
            attach: Some(NoteAttach { kind: ArchKind::Cabinet, object: ArchId(2), corner: Corner::TopLeft, ..Default::default() }),
            ..ViewNote::default()
        };
        let geometry = ViewGeometry {
            patterns: vec![ViewPatternLine {
                a: [0.0, 0.0],
                b: [1.0, 0.0],
                kind: ArchKind::Wall,
                object: ArchId(0),
                material: "wood".into(),
                ..Default::default()
            }],
            indicators: vec![ViewLine { a: [0.0, 0.0], b: [0.0, 1.0], kind: ArchKind::Opening, object: ArchId(1), ..Default::default() }],
            labels: vec![ViewLabel {
                text: "D1".into(),
                at: [1.0, 1.0],
                height: 0.1,
                layer: "A-ELEV-IDEN".into(),
                kind: ArchKind::Opening,
                object: ArchId(1),
                ..Default::default()
            }],
            ..Default::default()
        };
        m.views.push(ArchView {
            name: "I".into(),
            kind: ViewKind::Interior,
            room: Some(ArchId(1)),
            wall: Some(ArchId(5)),
            notes: vec![dim, attached],
            generated: Some(geometry),
            ..ArchView::default()
        });
        let rows = views_json(&m);
        let row = &rows[0];
        assert_eq!(row["kind"], "interior");
        assert_eq!(row["room"], "r1");
        assert_eq!(row["wall"], "w5");
        assert_eq!(row["patterns"][0]["id"], "w0");
        assert_eq!(row["patterns"][0]["material"], "wood");
        assert_eq!(row["indicators"][0]["id"], "o1");
        assert_eq!(row["labels"][0]["text"], "D1");
        assert_eq!(row["labels"][0]["id"], "o1");
        assert_eq!(row["notes"][0]["id"], "n0");
        assert_eq!(row["notes"][0]["kind"], "dimension");
        assert_eq!(row["notes"][0]["value"], 5.0);
        assert_eq!(row["notes"][0]["b"], json!([3.0, 4.0]));
        assert_eq!(row["notes"][1]["attach"], json!({ "object": "cb2", "corner": "topLeft" }));
        assert!(row["notes"][1]["value"].is_null());
        assert!(row["notes"][1]["b"].is_null());
        let mut m2 = ArchModel::default();
        m2.views.push(ArchView { name: "E".into(), ..ArchView::default() });
        let row = &views_json(&m2)[0];
        assert!(row["room"].is_null() && row["wall"].is_null());
        for k in ["patterns", "indicators", "labels", "notes"] {
            assert_eq!(row[k], json!([]), "{k}");
        }
    }

    use crate::Session;

    fn run(s: &mut Session, cmd: &str, p: Value) -> Result<Value> {
        s.execute(cmd, &p)
    }

    /// A 10 x 8 house split by an interior wall at x = 5 into a west room and an east room.
    fn two_rooms() -> (Session, String, String) {
        let mut s = Session::new();
        let ok = |r: Result<Value>| assert!(r.is_ok(), "{r:?}");
        ok(run(&mut s, "wall", json!({"points":[[0,0],[10,0],[10,8],[0,8],[0,0]],"thickness":0.2,"height":2.4,"exterior":true})));
        ok(run(&mut s, "wall", json!({"points":[[5,0],[5,8]],"thickness":0.2,"height":2.4})));
        ok(run(&mut s, "roomdetect", json!({})));
        let (west, east) = room_labels(&s);
        (s, west, east)
    }

    /// Labels of the rooms west and east of x = 5.
    fn room_labels(s: &Session) -> (String, String) {
        let arch = s.doc().map(|d| d.arch.clone()).unwrap_or_default();
        let at = |west: bool| {
            arch.rooms
                .iter()
                .find(|r| ((r.polygon.iter().map(|p| p.x).sum::<f64>() / r.polygon.len().max(1) as f64) < 5.0) == west)
                .map(|r| room_label(r.id))
                .unwrap_or_default()
        };
        (at(true), at(false))
    }

    #[test]
    fn interior_command_refusals() {
        let (mut s, west, east) = two_rooms();
        let before = s.doc().map(|d| (d.arch_revision, d.arch.views.len())).ok();
        let bads = [
            json!({"room": west}),
            json!({"room": west, "wall": "w9"}),
            json!({"room": west, "wall": "nope"}),
            json!({"room": west, "wall": 3}),
            json!({"room": west, "wall": "w0", "side": "east"}),
            json!({"room": west, "side": "up"}),
            json!({"room": west, "side": 4}),
            json!({"room": west, "side": "east", "look": [1, 0]}),
            json!({"room": west, "side": "east", "scope": [[0, 0], [1, 1]]}),
            json!({"room": "nobody", "side": "east"}),
            json!({"room": 7, "side": "east"}),
            json!({"room": "r99", "side": "east"}),
            json!({"room": west, "side": "east", "level": "Attic"}),
            json!({"room": west, "side": "east", "level": 5}),
            json!({"room": west, "side": "east", "level": true}),
            json!({"room": west, "side": "east", "scale": "x"}),
            json!({"room": west, "side": "east", "insert": [1]}),
            json!({"room": west, "side": "east", "name": 3}),
            json!({"room": west, "side": "east", "dimensions": "yes"}),
            // The east room's outer wall w1 (x = 10) does not bound the west room.
            json!({"room": west, "wall": "w1"}),
            json!({"room": east, "wall": "w3"}),
        ];
        for p in bads {
            let r = run(&mut s, "elevation", p.clone());
            assert!(r.is_err(), "{p} was accepted: {r:?}");
        }
        let after = s.doc().map(|d| (d.arch_revision, d.arch.views.len())).ok();
        assert_eq!(before, after);
        assert!(s.doc().is_ok_and(|d| d.arch.views.is_empty()));
    }

    #[test]
    fn interior_view_regenerates_live() {
        let (mut s, west, _) = two_rooms();
        let r = run(&mut s, "elevation", json!({"room": west, "side": "east"}));
        assert!(r.is_ok(), "{r:?}");
        let arch = s.doc().map(|d| d.arch.clone()).unwrap_or_default();
        let v = arch.views.first().cloned().unwrap_or_default();
        assert_eq!(v.kind, ViewKind::Interior);
        assert_eq!(v.look, [1.0, 0.0]);
        assert!(v.name.ends_with("East Interior"), "{}", v.name);
        let g = v.generated.clone().unwrap_or_default();
        assert!(g.error.is_none(), "{:?}", g.error);
        assert!(!g.lines.is_empty());
        // Every line lies within the room's width (y 0.1..7.9, so u = -y) and height.
        for l in &g.lines {
            for q in [l.a, l.b] {
                assert!(q[0] >= -7.9 - 1e-3 && q[0] <= -0.1 + 1e-3 && q[1] >= -1e-3 && q[1] <= 2.4 + 1e-3, "{q:?}");
            }
        }
        // Re-detecting renumbers the rooms; the view follows.
        let old = v.room;
        assert!(run(&mut s, "roomdetect", json!({})).is_ok());
        let arch = s.doc().map(|d| d.arch.clone()).unwrap_or_default();
        let v = arch.views.first().cloned().unwrap_or_default();
        assert_ne!(v.room, old);
        assert!(v.room.is_some_and(|id| arch.room(id).is_some()));
        assert!(v.generated.as_ref().is_some_and(|g| g.error.is_none() && !g.lines.is_empty()));
    }
}
